export function Metric({
  label = "{{label}}",
  value = {{value}},
  format = "{{format}}",
  size = {{size}},
  accent = "{{accent}}",
}) {
  const formatted = {
    plain: value.toLocaleString(),
    currency: `$${value.toLocaleString()}`,
    percent: `${value}%`,
  }[format] ?? value;
  return (
    <dl style={{ font: "16px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2",
      display: "inline-grid", gap: 4, padding: "20px 24px", borderRadius: 10, margin: 0 }}>
      <dt style={{ margin: 0, fontSize: 13, fontWeight: 600, letterSpacing: ".02em", color: accent, textTransform: "uppercase" }}>{label}</dt>
      <dd style={{ margin: 0, fontWeight: 700, lineHeight: 1, fontSize: size }}>{formatted}</dd>
    </dl>
  );
}
